package android.widget;import android.content.Context;import android.view.ViewGroup;public class GridLayout extends ViewGroup {public static final int UNDEFINED=-2147483648,ALIGN_BOUNDS=0;public int rows,columns;public GridLayout(Context c){super(c);}public void setRowCount(int n){rows=n;emit("grid_rows",n);}public void setColumnCount(int n){columns=n;emit("grid_columns",n);}public void setAlignmentMode(int n){emit("grid_alignment",n);}public static Spec spec(int start,int size,float weight){return new Spec(start,size,weight);}public static final class Spec{public final int start,size;public final float weight;Spec(int s,int n,float w){start=s;size=n;weight=w;}}public static class LayoutParams extends ViewGroup.MarginLayoutParams {public Spec rowSpec,columnSpec;public LayoutParams(){super(-2,-2);}}}